 444	/// Whether `<rev>:<path>` names an object; `--quiet` keeps a missing path from printing to stderr.
 445	fn head_object_exists<R: CommandRunner, D: DependencyResolver>(
 446	    ws: &Workspace<'_, R, D>,
 447	    spec: &str,
 448	) -> Result<bool, GraphError> {
 449	    let output = ws
 450	        .runner
 451	        .run("git", &["rev-parse", "--verify", "--quiet", spec], &ws.root)
 452	        .map_err(GraphError::Command)?;
 453	    match output.exit_code {
 454	        Some(0) => Ok(true),
 455	        Some(1) => Ok(false),
 456	        exit_code => Err(GraphError::Command(callisto_model::CommandError::Failed {
 457	            program: "git".to_string(),
 458	            exit_code,
 459	            stderr: output.stderr,
 460	        })),
 461	    }
 462	}
