 464	/// True when `HEAD`'s tree still has an unconsumed changeset file, read from the commit, not the working tree.
 465	fn head_has_pending_changeset<R: CommandRunner, D: DependencyResolver>(
 466	    ws: &Workspace<'_, R, D>,
 467	    head: &str,
 468	) -> Result<bool, GraphError> {
 469	    let dir = super::release_decision::normalized_git_path(&ws.config.changesets_dir)?;
 470	    let spec = format!("{head}:{dir}");
 471	    if !head_object_exists(ws, &spec)? {
 472	        // The changesets directory didn't exist at HEAD (e.g. the first `version` run); nothing left pending.
 473	        return Ok(false);
 474	    }
 475	    let output = ws
 476	        .runner
 477	        .run("git", &["ls-tree", "--name-only", &spec], &ws.root)
 478	        .map_err(GraphError::Command)?;
 479	    if !output.success() {
 480	        return Err(GraphError::Command(callisto_model::CommandError::Failed {
 481	            program: "git".to_string(),
 482	            exit_code: output.exit_code,
 483	            stderr: output.stderr,
 484	        }));
 485	    }
 486	    Ok(output.stdout.lines().any(|name| {
 487	        let name = name.trim();
 488	        name.ends_with(".md") && name != "README.md"
 489	    }))
 490	}
