 515	fn manifest_version_at<R: CommandRunner, D: DependencyResolver>(
 516	    ws: &Workspace<'_, R, D>,
 517	    head: &str,
 518	    path: &str,
 519	    cargo_root: Option<&str>,
 520	) -> Result<Option<callisto_manifests::EffectiveManifestVersion>, GraphError> {
 521	    let path = std::path::Path::new(path);
 522	    let Ok(format) = callisto_model::ManifestFormat::from_path(path) else {
 523	        return Ok(None);
 524	    };
 525	    let Some(source) = manifest_blob_at(ws, head, &path.to_string_lossy())? else {
 526	        return Ok(None);
 527	    };
 528	    Ok(callisto_manifests::read_effective_version(
 529	        format,
 530	        &source,
 531	        path,
 532	        cargo_root.map(|source| (std::path::Path::new("Cargo.toml"), source)),
 533	    )?)
 534	}
