 444	/// Whether `<rev>:<path>` names an object; `--quiet` keeps a missing path from printing to stderr.
 445	fn head_object_exists<R: CommandRunner, D: DependencyResolver>(
 446	    ws: &Workspace<'_, R, D>,
 447	    spec: &str,
 448	) -> Result<bool, GraphError> {
