 492	fn manifest_blob_at<R: CommandRunner, D: DependencyResolver>(
 493	    ws: &Workspace<'_, R, D>,
 494	    head: &str,
 495	    path: &str,
 496	) -> Result<Option<String>, GraphError> {
 497	    let spec = format!("{head}:{path}");
 498	    if !head_object_exists(ws, &spec)? {
 499	        return Ok(None);
 500	    }
 501	    let output = ws
 502	        .runner
 503	        .run("git", &["show", &spec], &ws.root)
 504	        .map_err(GraphError::Command)?;
 505	    if !output.success() {
 506	        return Err(GraphError::Command(callisto_model::CommandError::Failed {
 507	            program: "git".to_string(),
 508	            exit_code: output.exit_code,
 509	            stderr: output.stderr,
 510	        }));
 511	    }
 512	    Ok(Some(output.stdout))
 513	}
