 536	/// Platform manifest version writes and owner `optionalDependencies` pin updates
 537	/// for every owner with a target version in `targets`. Sources: each owner's
 538	/// attached platform manifests, plus `[[fixed-group]]`
 539	/// platform members.
 540	pub(crate) fn platform_version_writes<R: CommandRunner, D: DependencyResolver>(
 541	    ws: &Workspace<'_, R, D>,
 542	    targets: &std::collections::BTreeMap<callisto_model::PackageId, callisto_model::Version>,
 543	) -> Result<(Vec<PlatformWrite>, Vec<crate::plan::OptionalDepUpdate>), GraphError> {
 544	    let open_ctx = OpenContext::for_workspace_root(&ws.root);
 545	    let pkg_map: HashMap<_, _> = ws.graph.packages().map(|p| (&p.id, p)).collect();
 546	
 547	    let mut members: Vec<(&callisto_model::PackageId, &std::path::Path, &str)> = Vec::new();
 548	    for pkg in ws.graph.packages() {
 549	        members.extend(
 550	            ws.identity
 551	                .attached_platforms(pkg)
 552	                .map(|(name, path)| (&pkg.id, path, name)),
 553	        );
 554	    }
 555	    for group in ws.config.groups.fixed.values() {
 556	        for member in group.members(GroupMemberKind::PlatformManifest) {
 557	            if let GroupMember::PlatformManifest { owner, path, name, .. } = member {
 558	                members.push((owner, path, name));
 559	            }
 560	        }
 561	    }
 562	
 563	    let mut seen = HashSet::new();
 564	    let mut platform_writes = Vec::new();
 565	    let mut optional_dep_map: std::collections::BTreeMap<std::path::PathBuf, Vec<(String, callisto_model::Version)>> =
 566	        std::collections::BTreeMap::new();
 567	    for (owner, path, name) in members {
 568	        let Some(to) = targets.get(owner) else {
 569	            continue;
 570	        };
 571	        if !seen.insert(path) {
 572	            continue;
 573	        }
 574	        let fmt = callisto_model::ManifestFormat::from_path(path)?;
 575	        let decl = callisto_model::ManifestDecl::new(path, ManifestRole::Canonical, fmt)?;
 576	        let handle = open(&decl, &open_ctx)?;
 577	        let current = handle.current_version()?;
 578	        platform_writes.push(PlatformWrite {
 579	            manifest: path.to_path_buf(),
 580	            version: to.clone(),
 581	            from: current,
 582	        });
 583	
 584	        // A dual-manifest owner declares its platforms in package.json, not Cargo.toml.
 585	        for owner_decl in pkg_map.get(owner).into_iter().flat_map(|p| p.canonical_manifests()) {
 586	            let owner_fmt = callisto_model::ManifestFormat::from_path(&owner_decl.path)?;
 587	            let owner_manifest_decl =
 588	                callisto_model::ManifestDecl::new(owner_decl.path.clone(), ManifestRole::Canonical, owner_fmt)?;
 589	            // Cached: owner manifest is shared across every platform target under it.
 590	            let owner_handle = crate::manifest_cache::open_cached(&ws.manifest_cache, &owner_manifest_decl, &open_ctx)?;
 591	            if owner_handle
 592	                .iter_dependencies()
 593	                .any(|dep| dep.kind == callisto_model::DepKind::Optional && dep.name == name)
 594	            {
 595	                optional_dep_map
 596	                    .entry(owner_decl.path.clone())
 597	                    .or_default()
 598	                    .push((name.to_string(), to.clone()));
 599	                break;
 600	            }
 601	        }
 602	    }
 603	    let optional_dep_updates = optional_dep_map
 604	        .into_iter()
 605	        .map(|(manifest, updates)| crate::plan::OptionalDepUpdate { manifest, updates })
 606	        .collect();
 607	    Ok((platform_writes, optional_dep_updates))
 608	}
