   380	/// True when an untracked or tracked changeset remains in the configured directory on disk.
   381	fn working_tree_has_pending_changeset<R: CommandRunner, D: DependencyResolver>(
   382	    ws: &Workspace<'_, R, D>,
   383	) -> Result<bool, GraphError> {
   384	    let dir = ws.root.join(&ws.config.changesets_dir);
   385	    let entries = match std::fs::read_dir(&dir) {
   386	        Ok(entries) => entries,
   387	        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(false),
   388	        Err(error) => {
   389	            return Err(GraphError::ApplyIo {
   390	                path: ws.config.changesets_dir.clone(),
   391	                message: error.to_string(),
   392	            })
   393	        }
   394	    };
   395	    for entry in entries {
   396	        let entry = entry.map_err(|error| GraphError::ApplyIo {
   397	            path: ws.config.changesets_dir.clone(),
   398	            message: error.to_string(),
   399	        })?;
   400	        let name = entry.file_name();
   401	        let name = name.to_string_lossy();
   402	        let is_file = entry.file_type().map_err(|error| GraphError::ApplyIo {
   403	            path: ws.config.changesets_dir.join(&*name),
   404	            message: error.to_string(),
   405	        })?;
   406	        if is_file.is_file() && name.ends_with(".md") && name != "README.md" {
   407	            return Ok(true);
   408	        }
   409	    }
   410	    Ok(false)
   411	}
