  3	use callisto_graph::apply::{apply_version_plan, ApplyOptions, ApplyOutcome};
  4	use callisto_graph::commands::VersionOptions;
  5	use callisto_model::{ApplyPermit, DiagnosticSeverity};
  6	
  7	use crate::cli::{GlobalArgs, OutputFormat, VersionArgs};
  8	use crate::error::CliError;
  9	use crate::output::{emit_line, emit_report};
 10	use crate::render;
 11	use crate::runner::CliCommandRunner;
 12	use crate::workspace::{load_workspace, select_inference};
 13	
 14	pub fn handle(args: VersionArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
 15	    if global.dry_run && args.emit_decision.is_some() {
 16	        return Err(CliError::VersionEmitDecisionDryRun);
 17	    }
 18	
 19	    let runner = CliCommandRunner;
 20	    let ws = load_workspace(global, &runner)?;
 21	
 22	    let inference = select_inference();
 23	    let opts = VersionOptions {
 24	        strict: args.strict,
 25	        allow_empty_changesets: args.allow_empty_changesets,
 26	    };
 27	
 28	    let plan = callisto_graph::commands::plan_version(&ws, &inference, &opts)?;
 29	
 30	    // Refuses when disk already shows a bump HEAD lacks while release inputs or staged version state remain.
 31	    callisto_graph::commands::check_partial_run(&ws)?;
 32	
 33	    // Escalated diagnostics (e.g. --strict on "no pending changesets") must fail before anything is written.
 34	    let has_errors = plan.diagnostics.iter().any(|d| d.severity == DiagnosticSeverity::Error);
 35	
 36	    let permit = ApplyPermit::granted_unless_dry_run(global.dry_run);
 37	
 38	    // Derived before any write so an invalid plan fails early; written only after apply succeeds.
 39	    let pending_decision = if !has_errors {
 40	        match args.emit_decision.as_deref() {
 41	            Some(path) => {
 42	                let decision = callisto_graph::commands::derive_release_decision(&ws, &plan)?;
 43	                // Workspace-root-relative, not cwd-relative, so `git add -A` and a later `--decision` `git show` agree.
 44	                Some((ws.root.join(path), decision))
 45	            }
 46	            None => None,
 47	        }
 48	    } else {
 49	        None
 50	    };
 51	
 52	    let apply_opts = ApplyOptions {
 53	        refresh_lockfiles: !args.no_refresh_lockfiles,
 54	        transient: false,
 55	    };
 56	
 57	    let outcome = if has_errors {
 58	        ApplyOutcome::default()
 59	    } else {
 60	        match permit.as_ref() {
 61	            Some(permit) => apply_version_plan(&ws.root, &plan, &runner, &apply_opts, permit)?,
 62	            None => ApplyOutcome::default(),
 63	        }
 64	    };
 65	
 66	    if let (Some((full_path, decision)), Some(permit)) = (pending_decision.as_ref(), permit.as_ref()) {
 67	        let content = serde_json::to_string_pretty(decision).expect("release decision serializes") + "\n";
 68	        callisto_model::atomic::atomic_write(full_path, &content, permit).map_err(|source| CliError::Io {
 69	            source,
 70	            path: Some(full_path.clone()),
 71	        })?;
 72	    }
 73	
 74	    let report = plan.to_report(outcome.lockfile_refresh_results);
 75	
 76	    if global.dry_run && global.format == OutputFormat::Text {
 77	        emit_line("[DRY-RUN] Version Plan Calculated (no files modified):")?;
 78	    }
 79	
 80	    match global.format {
 81	        OutputFormat::Json => emit_report(&mut std::io::stdout(), &report, global.dry_run)?,
 82	        OutputFormat::Text => render::render_version(&report, &ws.config, &mut std::io::stdout())?,
 83	    }
 84	
 85	    // Mirrors the pattern in status.rs: diagnostics ride in the report so the
 86	    // caller sees full detail before the non-zero exit.
 87	    if has_errors {
 88	        Ok(ExitCode::FAILURE)
 89	    } else {
 90	        Ok(ExitCode::SUCCESS)
 91	    }
 92	}
