1233	    /// A `CommandRunner` whose configured program always fails with a fixed
1234	    /// exit code and stderr; every other program succeeds.
1235	    struct FailingProgramRunner {
1236	        failing_program: &'static str,
1237	        exit_code: i32,
1238	        stderr: &'static str,
1239	    }
1240	
1241	    struct FailingGitRmRunner {
1242	        calls: std::sync::Arc<std::sync::Mutex<Vec<Vec<String>>>>,
1243	    }
1244	
1245	    impl CommandRunner for FailingGitRmRunner {
1246	        fn run(&self, program: &str, args: &[&str], _cwd: &Path) -> Result<CommandOutput, CommandError> {
1247	            self.calls
1248	                .lock()
1249	                .unwrap()
1250	                .push(args.iter().map(|arg| (*arg).to_string()).collect());
1251	            let fails = program == "git" && args.first() == Some(&"rm");
1252	            Ok(CommandOutput {
1253	                exit_code: Some(if fails { 1 } else { 0 }),
1254	                stdout: String::new(),
1255	                stderr: if fails {
1256	                    "index removal failed".to_string()
1257	                } else {
1258	                    String::new()
1259	                },
1260	            })
1261	        }
1262	    }
1263	
1264	    impl CommandRunner for FailingProgramRunner {
1265	        fn run(&self, program: &str, _args: &[&str], _cwd: &Path) -> Result<CommandOutput, CommandError> {
1266	            if program == self.failing_program {
1267	                return Ok(CommandOutput {
1268	                    exit_code: Some(self.exit_code),
1269	                    stdout: String::new(),
1270	                    stderr: self.stderr.to_string(),
1271	                });
1272	            }
1273	            Ok(CommandOutput {
1274	                exit_code: Some(0),
1275	                stdout: String::new(),
1276	                stderr: String::new(),
1277	            })
1278	        }
1279	    }
