2336	        std::fs::write(&b_path, b_original).unwrap();
2337	
2338	        let a_rel = PathBuf::from("a-crate/Cargo.toml");
2339	        let b_rel = PathBuf::from("b-crate/Cargo.toml");
2340	
2341	        // b-crate's PlannedBump is listed FIRST and a-crate's SECOND, deliberately
2342	        // reversed from lexicographic path order, so plan-encounter order and
2343	        // BTreeMap path order disagree -- see this task's own reasoning.
2344	        let plan = VersionPlan {
2345	            bumps: vec![
2346	                PlannedBump {
2347	                    package: PackageId::parse("cargo:crate-b").unwrap(),
2348	                    from: cargo_version("1.0.0"),
