2368	        let permit = ApplyPermit::force_for_tests();
2369	        let opts = ApplyOptions::default();
2370	
2371	        let original_mode = std::fs::metadata(&b_dir).unwrap().permissions().mode();
2372	        std::fs::set_permissions(&b_dir, std::fs::Permissions::from_mode(0o555)).unwrap();
2373	
2374	        let probe_path = b_dir.join(".rtk-write-probe");
2375	        let probe_write_succeeded = std::fs::write(&probe_path, b"probe").is_ok();
2376	        if probe_write_succeeded {
2377	            std::fs::remove_file(&probe_path).ok();
2378	            std::fs::set_permissions(&b_dir, std::fs::Permissions::from_mode(original_mode)).unwrap();
2379	            eprintln!(
2380	                "skipping batched_groups_process_strictly_sequentially_in_btreemap_path_order: \
2381	                 process can write into a 0o555 directory (likely running as root); chmod-based failure injection is a no-op here"
2382	            );
2383	            return;
2384	        }
