 576	/// Maps a non-zero exit to `GraphError::LockfileRefreshFailed`, an exec failure to `GraphError::Command`.
 577	fn run_lockfile_refresh<R: CommandRunner>(
 578	    runner: &R,
 579	    root: &Path,
 580	    filename: &str,
 581	    program: &str,
 582	    args: &[&str],
 583	) -> Result<LockfileRefreshResult, GraphError> {
 584	    let refresh_command = format!("{program} {}", args.join(" "));
 585	    let out = runner.run(program, args, root)?;
 586	    if !out.success() {
 587	        return Err(GraphError::LockfileRefreshFailed {
 588	            filename: PathBuf::from(filename),
 589	            refresh_command,
 590	            exit_code: out.exit_code,
 591	            stderr: out.redacted_stderr(),
 592	        });
 593	    }
 594	    Ok(LockfileRefreshResult {
 595	        filename: PathBuf::from(filename),
 596	        refresh_command,
 597	        success: true,
 598	        exit_code: out.exit_code,
 599	    })
 600	}
