   144	    for (path, group) in &classification.batched {
   145	        let fmt = callisto_model::ManifestFormat::from_path(path)?;
   146	        let decl = callisto_model::ManifestDecl::new(path.clone(), ManifestRole::Canonical, fmt)?;
   147	        let mut handle = open(&decl, &ctx)?;
   148	        let mut mutated = false;
   149	
   150	        if let Some((bump_idx, target_version)) = &group.bump {
   151	            let bump = &plan.bumps[*bump_idx];
   152	            let current = handle.current_version()?;
   153	            if current == *target_version {
   154	                // Already at target — skip write, fall through to rewrites.
   155	            } else if current == bump.from {
   156	                handle.write_version(target_version, permit)?;
   157	                mutated = true;
   158	            } else {
   159	                return Err(GraphError::UnexpectedManifestVersion {
   160	                    path: path.clone(),
   161	                    expected_from: bump.from.clone(),
   162	                    expected_to: bump.to.clone(),
   163	                    found: current,
   164	                });
   165	            }
   166	        }
