   276	                    continue;
   277	                }
   278	                let mut ws_res = WorkspaceCargoResolver::load(&root.join(root_manifest))?;
   279	                ws_res.write_dependency(&rewrite.key.name, rewrite.to.clone(), permit)?;
   280	                ws_res.persist(permit)?;
   281	                modified_paths.push(root_manifest.clone());
   282	            }
   283	        }
   284	    }
   285	
   286	    for pw in &plan.platform_writes {
   287	        let fmt = callisto_model::ManifestFormat::from_path(&pw.manifest)?;
   288	        let decl = callisto_model::ManifestDecl::new(pw.manifest.clone(), ManifestRole::Canonical, fmt)?;
   289	        let mut handle = open(&decl, &ctx)?;
   290	        let current = handle.current_version()?;
   291	        if current == pw.version {
   292	            // Already at target — skip write, but still stage so git add re-stages on retry.
