413	/// True when a canonical manifest differs between index and HEAD: `git add`ed by a prior `apply` but never committed.
414	fn any_canonical_manifest_staged_uncommitted<R: CommandRunner, D: DependencyResolver>(
415	    ws: &Workspace<'_, R, D>,
416	) -> Result<bool, GraphError> {
417	    let mut paths = std::collections::BTreeSet::new();
418	    for decl in ws.graph.packages().flat_map(|pkg| pkg.canonical_manifests()) {
419	        paths.insert(super::release_decision::normalized_git_path(&decl.path)?);
420	        if decl.ecosystem() == callisto_model::Ecosystem::Cargo {
421	            paths.insert("Cargo.toml".to_string());
422	        }
423	    }
424	    for path in paths {
425	        let output = ws
426	            .runner
427	            .run("git", &["diff", "--cached", "--quiet", "--", &path], &ws.root)
428	            .map_err(GraphError::Command)?;
429	        match output.exit_code {
430	            Some(0) => {}
431	            Some(1) => return Ok(true),
432	            exit_code => {
433	                return Err(GraphError::Command(callisto_model::CommandError::Failed {
434	                    program: "git".to_string(),
435	                    exit_code,
436	                    stderr: output.stderr,
437	                }))
438	            }
439	        }
440	    }
441	    Ok(false)
442	}
