312	/// Refuses when a canonical manifest version differs from `HEAD` while release inputs remain or the change is staged.
313	pub fn check_partial_run<R: CommandRunner, D: DependencyResolver>(ws: &Workspace<'_, R, D>) -> Result<(), GraphError> {
314	    let head = match ws.git_access().head_sha() {
315	        Ok(head) => head,
316	        Err(error) => {
317	            let output = ws
318	                .runner
319	                .run("git", &["rev-parse", "--verify", "--quiet", "HEAD"], &ws.root)
320	                .map_err(GraphError::Command)?;
321	            match output.exit_code {
322	                Some(1) => return Ok(()),
323	                Some(0) => return Err(error.into()),
324	                exit_code => {
325	                    return Err(GraphError::Command(callisto_model::CommandError::Failed {
326	                        program: "git".to_string(),
327	                        exit_code,
328	                        stderr: output.stderr,
329	                    }))
330	                }
331	            }
332	        }
333	    };
334	    let head = head.as_str();
335	
336	    // A pre-release cycle legitimately reruns `version` uncommitted; the staged-manifest check is scoped past it.
337	    let in_pre_release_cycle = ws.root.join(ws.config.pre_json_path()).exists();
338	
339	    let staged_manifests = if in_pre_release_cycle {
340	        BTreeSet::new()
341	    } else {
342	        canonical_manifest_staged_paths(ws)?
343	    };
344	    let pending = !in_pre_release_cycle
345	        && (head_has_pending_changeset(ws, head)?
346	            || working_tree_has_pending_changeset(ws)?
347	            || !staged_manifests.is_empty());
348	    if !pending {
349	        return Ok(());
350	    }
351	
352	    let cargo_root = if ws
353	        .graph
354	        .packages()
355	        .flat_map(|pkg| pkg.canonical_manifests())
356	        .any(|decl| decl.ecosystem() == callisto_model::Ecosystem::Cargo)
357	    {
358	        manifest_blob_at(ws, head, "Cargo.toml")?
359	    } else {
360	        None
361	    };
362	    let cargo_root_index = if staged_manifests.contains("Cargo.toml") {
363	        manifest_blob_in_index(ws, "Cargo.toml")?
364	    } else {
365	        None
366	    };
367	    let base_versions = ws.base_versions()?;
368	    for pkg in ws.graph.packages() {
369	        let Some(disk) = base_versions.get(&pkg.id) else {
370	            continue;
371	        };
372	        for decl in pkg.canonical_manifests() {
373	            let path = super::release_decision::normalized_git_path(&decl.path)?;
374	            let Some(head_version) = manifest_version_at(ws, head, &path, cargo_root.as_deref())? else {
375	                continue;
376	            };
377	            let index_path_changed = staged_manifests.contains(&path)
378	                || (decl.ecosystem() == callisto_model::Ecosystem::Cargo && staged_manifests.contains("Cargo.toml"));
379	            let index_version = if index_path_changed {
380	                manifest_version_in_index(ws, &path, cargo_root_index.as_deref())?
381	            } else {
382	                None
383	            };
384	            let index_display = match &index_version {
385	                Some(version) => version.version.render().to_string(),
386	                None if index_path_changed => "absent".to_string(),
387	                None => head_version.version.render().to_string(),
388	            };
389	            let index_differs = index_path_changed
390	                && index_version
391	                    .as_ref()
392	                    .is_none_or(|version| version.version != head_version.version);
393	            if *disk != head_version.version || index_differs {
394	                return Err(GraphError::PartialVersionRun {
395	                    path: head_version.authority,
396	                    disk: disk.clone(),
397	                    index: index_display,
398	                    head: head_version.version,
399	                });
400	            }
401	        }
402	    }
403	
404	    Ok(())
405	}
