441	fn canonical_manifest_staged_paths<R: CommandRunner, D: DependencyResolver>(
442	    ws: &Workspace<'_, R, D>,
443	) -> Result<BTreeSet<String>, GraphError> {
444	    let mut paths = BTreeSet::new();
445	    for decl in ws.graph.packages().flat_map(|pkg| pkg.canonical_manifests()) {
446	        paths.insert(super::release_decision::normalized_git_path(&decl.path)?);
447	        if decl.ecosystem() == callisto_model::Ecosystem::Cargo {
448	            paths.insert("Cargo.toml".to_string());
449	        }
450	    }
451	    let mut staged = BTreeSet::new();
452	    for path in paths {
453	        let output = ws
454	            .runner
455	            .run("git", &["diff", "--cached", "--quiet", "--", &path], &ws.root)
456	            .map_err(GraphError::Command)?;
457	        match output.exit_code {
458	            Some(0) => {}
459	            Some(1) => {
460	                staged.insert(path);
461	            }
462	            exit_code => {
463	                return Err(GraphError::Command(callisto_model::CommandError::Failed {
464	                    program: "git".to_string(),
465	                    exit_code,
466	                    stderr: output.stderr,
467	                }))
468	            }
469	        }
470	    }
471	    Ok(staged)
472	}
